using HRM.Models.Recruitment;
using HRM.Models;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace HRM.Api.Data.EntityConfigurations;

public sealed class RecruitmentComplianceMapping : IEntityTypeConfiguration<RecruitmentPolicyProfile>, IEntityTypeConfiguration<RecruitmentPolicyVersion>, IEntityTypeConfiguration<RecruitmentComplianceRule>, IEntityTypeConfiguration<RecruitmentPolicyAssignment>
{
    public void Configure(EntityTypeBuilder<RecruitmentPolicyProfile> b) { b.ToTable("RM_RecruitmentPolicyProfiles"); b.HasKey(x => x.Id); b.Property(x => x.Code).HasMaxLength(64).IsUnicode(false).IsRequired(); b.Property(x => x.Name).HasMaxLength(200).IsRequired(); b.Property(x => x.Jurisdiction).HasMaxLength(100).IsRequired(); b.Property(x => x.Version).IsConcurrencyToken(); b.HasIndex(x => x.Code).IsUnique(); }
    public void Configure(EntityTypeBuilder<RecruitmentPolicyVersion> b) { b.ToTable("RM_RecruitmentPolicyVersions"); b.HasKey(x => x.Id); b.Property(x => x.VersionCode).HasMaxLength(80).IsRequired(); b.Property(x => x.OfficialSourceUrl).HasMaxLength(2048).IsRequired(); b.Property(x => x.OfficialSourceReference).HasMaxLength(500).IsRequired(); b.Property(x => x.VerificationStatus).HasMaxLength(40).IsRequired(); b.Property(x => x.EffectiveFrom).HasColumnType("date"); b.Property(x => x.EffectiveTo).HasColumnType("date"); b.Property(x => x.Version).IsConcurrencyToken(); b.HasIndex(x => new { x.RecruitmentPolicyProfileId, x.VersionCode }).IsUnique(); b.HasOne(x => x.RecruitmentPolicyProfile).WithMany().HasForeignKey(x => x.RecruitmentPolicyProfileId).OnDelete(DeleteBehavior.Restrict); b.HasOne<User>().WithMany().HasForeignKey(x => x.VerifiedByUserId).OnDelete(DeleteBehavior.Restrict); }
    public void Configure(EntityTypeBuilder<RecruitmentComplianceRule> b) { b.ToTable("RM_RecruitmentComplianceRules"); b.HasKey(x => x.Id); b.Property(x => x.RuleCode).HasMaxLength(100).IsUnicode(false).IsRequired(); b.Property(x => x.Requirement).HasMaxLength(2000).IsRequired(); b.Property(x => x.OfficialProvision).HasMaxLength(500).IsRequired(); b.Property(x => x.RecruitmentType).HasMaxLength(60).IsRequired(); b.Property(x => x.PositionCategory).HasMaxLength(100).IsRequired(); b.Property(x => x.EnforcementLevel).HasMaxLength(30).IsRequired(); b.Property(x => x.ValidationDefinitionJson).HasMaxLength(8000).IsRequired(); b.Property(x => x.ResponsibleAuthority).HasMaxLength(200).IsRequired(); b.Property(x => x.VerificationStatus).HasMaxLength(40).IsRequired(); b.Property(x => x.Version).IsConcurrencyToken(); b.HasIndex(x => new { x.RecruitmentPolicyVersionId, x.RuleCode }).IsUnique(); b.HasOne(x => x.RecruitmentPolicyVersion).WithMany().HasForeignKey(x => x.RecruitmentPolicyVersionId).OnDelete(DeleteBehavior.Restrict); }
    public void Configure(EntityTypeBuilder<RecruitmentPolicyAssignment> b) { b.ToTable("RM_RecruitmentPolicyAssignments"); b.HasKey(x => x.Id); b.Property(x => x.RecruitmentType).HasMaxLength(60).IsRequired(); b.Property(x => x.PositionCategory).HasMaxLength(100).IsRequired(); b.Property(x => x.EffectiveFrom).HasColumnType("date"); b.Property(x => x.EffectiveTo).HasColumnType("date"); b.Property(x => x.Version).IsConcurrencyToken(); b.HasIndex(x => new { x.OrganisationId, x.RecruitmentType, x.PositionCategory, x.EffectiveFrom }).IsUnique(); b.HasOne<Organisation>().WithMany().HasForeignKey(x => x.OrganisationId).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.RecruitmentPolicyVersion).WithMany().HasForeignKey(x => x.RecruitmentPolicyVersionId).OnDelete(DeleteBehavior.Restrict); b.HasOne<OperationLog>().WithMany().HasForeignKey(x => x.OperationLogId).OnDelete(DeleteBehavior.Restrict); }
}

